AULAS["_5GZqUvGT4g"] = aula_en(
    "<i>Could</i> tem dois usos principais: o passado de <i>can</i> (<i>I could swim when I was five</i>, eu sabia/conseguia) e a forma educada de pedir ou sugerir (<i>Could you help me?</i>, você poderia?).",
    ["usar <i>could</i> como passado de <i>can</i>;", "fazer pedidos educados com <i>Could you ...?</i>;", "sugerir com <i>We could ...</i>"],
    ("Qual pedido é mais educado?", ["Can you send me the file?", "Could you send me the file, please?", "Send me the file."], 1,
     ["Correto, mas um pouco menos formal.", "Isso! <i>Could you ..., please?</i> é a forma mais educada.", "Soa como ordem."],
     "Pedido educado: Could you ...?"),
    ("Pedindo ajuda", [
        ("Rosa", "Excuse me, could you help me with this form?", "Com licença, poderia me ajudar com este formulário?"),
        ("Clerk", "Of course. Could you show me your ID?", "Claro. Poderia mostrar seu documento?"),
        ("Rosa", "Here it is. When I was younger, I could do this online.", "Aqui está. Quando eu era mais nova, dava para fazer isso online."),
        ("Clerk", "We could do it online now, but the system is down.", "Poderíamos fazer online agora, mas o sistema está fora do ar."),
    ]),
    "os usos do could",
    tabela("Could", ["Uso", "Exemplo"], [
        ["Habilidade no passado", "I could read when I was four."], ["Pedido educado", "Could you open the window, please?"], ["Permissão educada", "Could I ask you something?"],
        ["Sugestão", "We could go to the beach."], ["Possibilidade", "It could rain later."],
    ], corpo="<p>Negativa: <i>couldn't</i> (<i>I couldn't sleep</i>, não consegui dormir).</p>"),
    [("Could you ...?", "Você poderia ...?", "Could you repeat that?"), ("Could I ...?", "Eu poderia ...?", "Could I use your phone?"), ("couldn't", "não conseguia / não consegui", "I couldn't sleep last night."),
     ("We could ...", "Poderíamos ...", "We could order pizza."), ("When I was a kid, I could ...", "Quando criança, eu conseguia ...", "When I was a kid, I could run fast."), ("Here it is.", "Aqui está.", "Your ID? Here it is.")],
    [("Could you repeat that?", ["Poderia repetir?", "Você repetiu?", "Pode ir embora?"], 0, "Poderia repetir?"),
     ("I couldn't sleep last night.", ["Não consegui dormir ontem à noite", "Dormi bem ontem", "Não vou dormir"], 0, "Não consegui dormir."),
     ("We could order pizza.", ["Poderíamos pedir pizza", "Pedimos pizza", "Não podemos pedir pizza"], 0, "Poderíamos pedir pizza."),
     ("Could I ask a question?", "5 palavras"), ("I couldn't find it.", "4 palavras (contando a contração)")],
    [("Could you help me, please?", "Poderia me ajudar, por favor?"), ("Could I ask you something?", "Posso te perguntar uma coisa?"), ("I couldn't find the file.", "Não consegui achar o arquivo."), ("We could meet tomorrow.", "Poderíamos nos encontrar amanhã.")],
    [("<i>Could you to help?</i>", "<i>Could you help?</i>"), ("<i>I could to swim</i>.", "<i>I could swim</i>."), ("Usar <i>could</i> para um sucesso pontual no passado: <i>I could pass the exam yesterday</i>.", "Para uma conquista específica: <i>I was able to pass</i> / <i>I managed to pass</i>.")],
    "<p>Em e-mails e reuniões: <b>Could you take a look at this?</b>, <b>Could we move the meeting to 3 p.m.?</b>, <b>I couldn't reproduce the bug</b>, <b>We could try a different approach</b>.</p>",
    [("Pedido mais educado:", ["Can you help?", "Could you help, please?", "Help me."], 1, "Could."),
     ("Passado de <i>can</i>:", ["canned", "could", "can't"], 1, "could."),
     ("“Não consegui reproduzir o bug”:", ["I can't reproduced the bug.", "I couldn't reproduce the bug.", "I didn't could reproduce."], 1, "couldn't + base.")],
    ["could = passado de can (habilidade).", "Pedidos e permissões educadas: <i>Could you/I ...?</i>", "Sugestões: <i>We could ...</i>"],
    "Aula 10: pronomes possessivos.", "could you take a look")

AULAS["-_unckJkFIc"] = aula_en(
    "Há dois tipos de possessivo: os que vêm <b>antes</b> do substantivo (<i>my book</i>) e os que <b>substituem</b> o substantivo (<i>it's mine</i>). <i>Mine, yours, his, hers, ours, theirs</i> evitam repetir a palavra.",
    ["diferenciar adjetivos possessivos e pronomes possessivos;", "usar <i>mine, yours, hers</i>...;", "perguntar <i>Whose is this?</i>"],
    ("“Este celular é seu?”", ["Is this phone your?", "Is this phone yours?", "Is this your's phone?"], 1,
     ["<i>Your</i> precisa de um substantivo depois.", "Isso! Sozinho, no fim: <i>yours</i>.", "Não existe <i>your's</i>."],
     "Antes do substantivo: my/your. Sozinho: mine/yours."),
    ("De quem é?", [
        ("Teacher", "Whose bag is this?", "De quem é esta bolsa?"),
        ("Bia", "It's not mine. Maybe it's Carla's.", "Não é minha. Talvez seja da Carla."),
        ("Carla", "Yes, it's mine! Thanks.", "Sim, é minha! Obrigada."),
        ("Teacher", "And these keys? Are they yours?", "E estas chaves? São suas?"),
        ("Bia", "No, ours are on the table.", "Não, as nossas estão na mesa."),
    ]),
    "os dois tipos de possessivo",
    tabela("Possessivos", ["Pessoa", "Antes do substantivo", "Sozinho"], [
        ["I", "my", "mine"], ["you", "your", "yours"], ["he", "his", "his"], ["she", "her", "hers"], ["we", "our", "ours"], ["they", "their", "theirs"],
    ], corpo="<p>Pergunta: <i>Whose ... is this?</i> (de quem é?). Com nome: <i>It's Carla's.</i></p>"),
    [("mine", "meu / minha (sozinho)", "This book is mine."), ("yours", "seu / sua (sozinho)", "Is this yours?"), ("hers", "dela", "The red car is hers."),
     ("ours", "nosso(a)", "Ours is the blue house."), ("theirs", "deles", "The idea was theirs."), ("Whose ...?", "De quem ...?", "Whose phone is this?")],
    [("Is this yours?", ["Isto é seu?", "Isto é meu?", "Você quer isto?"], 0, "Isto é seu?"),
     ("Whose phone is this?", ["De quem é este celular?", "Onde está o celular?", "Quem ligou?"], 0, "De quem é este celular?"),
     ("The idea was theirs.", ["A ideia foi deles", "A ideia foi nossa", "A ideia está lá"], 0, "A ideia foi deles."),
     ("It's not mine.", "3 palavras (contando a contração)"), ("This book is mine.", "4 palavras")],
    [("Whose bag is this?", "De quem é esta bolsa?"), ("It's not mine, it's hers.", "Não é minha, é dela."), ("Is this seat yours?", "Este lugar é seu?"), ("Our office is bigger than theirs.", "Nosso escritório é maior que o deles.")],
    [("<i>It's my.</i>", "<i>It's mine.</i>"), ("<i>your's / her's</i>.", "Sem apóstrofo: <i>yours, hers</i>."), ("Confundir <i>whose</i> (de quem) e <i>who's</i> (who is).", "<i>Whose book?</i> × <i>Who's there?</i>")],
    "<p>Em revisões: <b>Is this change yours or mine?</b>, <b>Their API is faster than ours</b>, <b>Whose task is this?</b> (de quem é esta tarefa?).</p>",
    [("Complete: “That car is ___.” (dele)", ["him", "his", "he's"], 1, "his."),
     ("“Este é o nosso”:", ["This is our.", "This is ours.", "This is our's."], 1, "ours."),
     ("“De quem é?”:", ["Who's is it?", "Whose is it?", "Who is it of?"], 1, "whose.")],
    ["my/your/his/her/our/their + substantivo.", "mine/yours/his/hers/ours/theirs sozinhos.", "<i>Whose ...?</i> pergunta o dono."],
    "Aula 11: falando de hábitos passados (used to).", "is this yours")

