    [("<i>I didn't used to</i>.", "Com <i>did</i>, sem -d: <i>I didn't use to</i>."), ("<i>I use to</i> para hábito atual.", "Hábito atual usa presente: <i>I usually ...</i>"), ("Confundir com <i>be used to</i>.", "<i>I'm used to</i> = estou acostumado (aula do Módulo 5).")],
    "<p>Para contar sua trajetória numa entrevista: <b>I used to work in sales, but now I'm a data analyst</b>. Em discussões técnicas: <b>We used to deploy manually; now it's automated</b>.</p>",
    [("Complete: “I ___ live in Natal.” (não moro mais)", ["use to", "used to", "am used to"], 1, "used to."),
     ("Negativa correta:", ["I didn't used to.", "I didn't use to.", "I usedn't."], 1, "Sem -d."),
     ("“Não jogo mais”:", ["I don't play anymore.", "I play no more now.", "I didn't play still."], 0, "anymore.")],
