    [("There were many people at the party.", "Havia muitas pessoas na festa."), ("There will be a meeting tomorrow.", "Haverá uma reunião amanhã."), ("Was there a problem?", "Houve algum problema?"), ("There would be no problem.", "Não haveria problema.")],
    [("<i>There was many people</i>.", "Plural: <i>There were</i>."), ("<i>Will have a meeting</i>.", "<i>There will be a meeting</i>."), ("<i>There will have</i>.", "<i>There will <b>be</b></i>.")],
