    [("“Havia dois erros”:", ["There was two errors.", "There were two errors.", "There had two errors."], 1, "Plural."),
     ("“Haverá uma festa”:", ["There will be a party.", "Will have a party.", "There will has a party."], 0, "will be."),
     ("“Houve algum problema?”:", ["Was there a problem?", "Had a problem?", "There was problem?"], 0, "Inverte.")],
